// Discover ServiceMonitors and scrape metrics
prometheus.operator.servicemonitors "default" {
  namespaces = []
  forward_to = [prometheus.remote_write.vm.receiver]
}

prometheus.operator.podmonitors "default" {
  namespaces = []
  forward_to = [prometheus.remote_write.vm.receiver]
}

// Kubelet cAdvisor - the source of every container CPU/memory series.
// Nothing was scraping it, which is why all pod/container resource
// panels rendered empty. Scraped directly on the kubelet's :10250
// rather than through the apiserver proxy, because the Alloy
// ClusterRole carries nodes/metrics but not nodes/proxy.
discovery.kubernetes "nodes" {
  role = "node"
}

discovery.relabel "cadvisor" {
  targets = discovery.kubernetes.nodes.targets
  rule {
    source_labels = ["__meta_kubernetes_node_name"]
    target_label  = "node"
  }
  rule {
    target_label = "__metrics_path__"
    replacement  = "/metrics/cadvisor"
  }
}

prometheus.scrape "cadvisor" {
  targets           = discovery.relabel.cadvisor.output
  job_name          = "kubelet-cadvisor"
  scheme            = "https"
  scrape_interval   = "60s"
  bearer_token_file = "/var/run/secrets/kubernetes.io/serviceaccount/token"
  tls_config {
    ca_file              = "/var/run/secrets/kubernetes.io/serviceaccount/ca.crt"
    insecure_skip_verify = true
  }
  forward_to = [prometheus.relabel.cadvisor_keep.receiver]
}

// Keep only the series the dashboards actually query. Measured against
// the live endpoints: this keep-list is 6580 series across the 3 nodes
// where an unfiltered scrape is 39222. Against a ~72550 baseline that
// is +9% rather than +54%, which matters because the VM Prometheus is
// capped at 10GB retention and /data is already 87% full (issue #3726).
prometheus.relabel "cadvisor_keep" {
  forward_to = [prometheus.remote_write.vm.receiver]
  rule {
    source_labels = ["__name__"]
    regex         = "container_(cpu_usage_seconds_total|cpu_cfs_periods_total|cpu_cfs_throttled_periods_total|memory_working_set_bytes|memory_rss|memory_cache|network_receive_bytes_total|network_transmit_bytes_total|fs_reads_bytes_total|fs_writes_bytes_total)"
    action        = "keep"
  }
}

// Blackbox probe targets for NFS health (replaces orphaned VMProbes)
discovery.relabel "blackbox_nfs" {
  targets = [{
    __address__    = "blackbox-exporter.observability:9115",
    __param_target = "nas.internal:2049",
    __param_module = "tcp_connect",
  }]
  rule {
    source_labels = ["__param_target"]
    target_label  = "instance"
  }
}

prometheus.scrape "blackbox_nfs" {
  targets      = discovery.relabel.blackbox_nfs.output
  job_name     = "blackbox-nfs"
  metrics_path = "/probe"
  forward_to   = [prometheus.remote_write.vm.receiver]
}

// Blackbox probe targets for ICMP health (nas, db)
discovery.relabel "blackbox_devices" {
  targets = [
    {
      __address__    = "blackbox-exporter.observability:9115",
      __param_target = "nas.internal",
      __param_module = "icmp",
    },
    {
      __address__    = "blackbox-exporter.observability:9115",
      __param_target = "db.internal",
      __param_module = "icmp",
    },
  ]
  rule {
    source_labels = ["__param_target"]
    target_label  = "instance"
  }
}

prometheus.scrape "blackbox_devices" {
  targets      = discovery.relabel.blackbox_devices.output
  job_name     = "blackbox-icmp"
  metrics_path = "/probe"
  forward_to   = [prometheus.remote_write.vm.receiver]
}

// Remote write to self-hosted Prometheus on VM (no auth, IP-allowlisted)
prometheus.remote_write "vm" {
  endpoint {
    url = env("PROMETHEUS_URL") + "/api/v1/write"
  }
}

// Discover log files matching the pod log pattern
local.file_match "pods" {
  path_targets = [
    {"__path__" = "/var/log/pods/*/*/*.log"},
  ]
}

// Copy __path__ to a non-internal label so it's available in loki.process
discovery.relabel "pods" {
  targets = local.file_match.pods.targets

  rule {
    source_labels = ["__path__"]
    target_label  = "filepath"
  }
}

// Collect container logs from /var/log/pods
loki.source.file "pods" {
  targets    = discovery.relabel.pods.output
  forward_to = [loki.process.add_k8s_labels.receiver]
}

// Extract Kubernetes metadata from the log file path
loki.process "add_k8s_labels" {
  stage.static_labels {
    values = {
      source = "k8s",
    }
  }
  stage.regex {
    expression = "^/var/log/pods/(?P<namespace>[^_]+)_(?P<pod>.+)_(?P<uid>[a-f0-9-]+)/(?P<container>[^/]+)/"
    source     = "filepath"
  }
  stage.labels {
    values = {
      namespace = "namespace",
      pod       = "pod",
      container = "container",
    }
  }
  forward_to = [loki.write.vm.receiver]
}

// Send logs to self-hosted Loki on VM (no auth, IP-allowlisted)
loki.write "vm" {
  endpoint {
    url = env("LOKI_URL") + "/loki/api/v1/push"
  }
}
